import { Table, StringColumn, BooleanColumn, ReferenceColumn, TranslatedTextColumn, GenericColumn } from '../../db'

export const sys_alias = Table({
    name: 'sys_alias',
    extends: 'sys_metadata',
    label: 'Connection & Credential Aliases',
    allowWebServiceAccess: true,
    schema: {
        name: StringColumn({
            mandatory: true,
            label: 'Name',
            attributes: {
                edge_encryption_enabled: true,
            },
            maxLength: 255,
        }),
        id: StringColumn({
            mandatory: false,
            label: 'ID',
            readOnly: true,
            attributes: {
                edge_encryption_enabled: true,
            },
            maxLength: 255,
        }),
        type: StringColumn({
            mandatory: true,
            label: 'Type',
            default: 'connection',
            attributes: {
                edge_encryption_enabled: true,
            },
            maxLength: 40,
            choices: {
                connection: {
                    label: 'Connection and Credential',
                    sequence: 0,
                },
                credential: {
                    label: 'Credential',
                    sequence: 0,
                },
            },
        }),
        connection_type: StringColumn({
            mandatory: false,
            label: 'Connection type',
            default: 'http_connection',
            attributes: {
                edge_encryption_enabled: true,
            },
            maxLength: 40,
            choices: {
                http_connection: {
                    label: 'HTTP',
                    sequence: 0,
                },
                jdbc_connection: {
                    label: 'JDBC',
                    sequence: 0,
                },
                sys_connection: {
                    label: 'Basic',
                    sequence: 0,
                },
                orch_jms_ds: {
                    label: 'JMS',
                    sequence: 0,
                },
            },
        }),
        description: TranslatedTextColumn({
            mandatory: false,
            label: 'Description',
            maxLength: 4000,
        }),
        parent: ReferenceColumn({
            mandatory: false,
            label: 'Parent Alias',
            attributes: {
                encode_utf8: false,
            },
            referenceTable: 'sys_alias',
        }),
        configuration_template: ReferenceColumn({
            mandatory: false,
            label: 'Configuration Template',
            attributes: {
                encode_utf8: false,
            },
            referenceTable: 'sys_alias_templates',
        }),
        retry_policy: ReferenceColumn({
            mandatory: false,
            label: 'Default Retry Policy',
            attributes: {
                encode_utf8: false,
            },
            referenceTable: 'sys_retry_policy',
        }),
        multiple_connections: BooleanColumn({
            mandatory: false,
            label: 'Support Multiple Active Connections',
            default: false,
        }),
        is_internal: BooleanColumn({
            mandatory: false,
            label: 'Is internal',
            default: false,
        }),
        sys_id: GenericColumn({
            mandatory: false,
            label: 'Sys ID',
            column_type: 'GUID',
        }),
    },
})
